-- RRTrack 2.0 - ATUALIZAR-2026-09-27-B-COMPACTO (versao compacta)
-- O SQL Editor do Supabase corta o script na linha 100; esta versao cabe.
-- Mesmo conteudo de ATUALIZAR-2026-09-27-B.sql, sem as quebras de linha. Cole tudo e rode.

alter table public.webhooks_recebidos add column if not exists purged_at timestamptz; comment on column public.webhooks_recebidos.purged_at is 'Quando a retenção zerou corpo/corpo_texto/headers. NULL = nunca zerada. Existe porque `corpo is null` também acontece quando o gateway manda algo que não é JSON, e a tela precisa dizer qual dos dois foi.'; /* * Índice do varredor: ele pede as mais antigas AINDA não zeradas, em ordem * crescente. Parcial, porque o estado normal de uma linha velha é já estar * zerada — sem o `where`, o índice cresceria com a tabela e a varredura * passaria por tudo que já foi feito. */ create index if not exists webhooks_recebidos_retencao_idx on public.webhooks_recebidos (created_at) where purged_at is null;
create or replace function private.aplicar_retencao(p_lote integer default 5000) returns table (tabela text, linhas bigint) language plpgsql security definer set search_path = '' as $$ declare v_n bigint; begin /* * EM LOTES, e `purged_at` é o que torna isso possível. * * Um UPDATE sobre seis meses de eventos trava a tabela por minutos e a * captura para de gravar — o site inteiro perde tracking enquanto a * limpeza roda. Com lote e marca, cada passagem é curta e a seguinte * continua de onde parou. */ with alvo as ( select id from public.events_log where created_at < now() - interval '14 days' and purged_at is null order by created_at limit p_lote for update skip locked ) update public.events_log e set payload_meta = null, response_meta = null, payload_ga4 = null, response_ga4 = null, purged_at = now() from alvo where e.id = alvo.id; get diagnostics v_n = row_count; tabela := 'events_log'; linhas := v_n; return next; /* * Aqui o prazo depende do ESTADO da linha, não só da idade. * * Verde (reconhecido, sem pendência) são a maioria e já cumpriram o papel: * 30 dias. Amarelo e vermelho ainda podem virar venda com um clique, e é * exatamente o corpo deles que o Reprocessar precisa: 90 dias. * * `purged_at is null` no lugar do antigo "algum dos três campos não é * nulo": a marca é o fato, e o teste pelos campos confundia linha zerada * com linha que chegou sem nada. De quebra, a primeira passagem estampa * as que já haviam sido zeradas antes desta migration — a data fica * aproximada nelas, mas o fato passa a estar registrado, que é o que a * tela precisa. (Neste banco não há nenhuma: nada chegou aos 30 dias.) */ with alvo as ( select id from public.webhooks_recebidos where purged_at is null and ( case when adaptador is not null and motivo is null then created_at < now() - interval '30 days' else created_at < now() - interval '90 days' end ) order by created_at limit p_lote for update skip locked ) update public.webhooks_recebidos w set corpo = null, corpo_texto = null, headers = null, purged_at = now() from alvo where w.id = alvo.id; get diagnostics v_n = row_count; tabela := 'webhooks_recebidos'; linhas := v_n; return next; with alvo as ( select id from public.purchases where created_at < now() - interval '90 days' and raw_webhook is not null order by created_at limit p_lote for update skip locked ) update public.purchases p set raw_webhook = null from alvo where p.id = alvo.id; get diagnostics v_n = row_count; tabela := 'purchases'; linhas := v_n; return next; end; $$;
comment on function private.aplicar_retencao(integer) is 'Zera os campos pesados fora do prazo, em lotes. NUNCA apaga linha: data, evento, UTMs e geo seguem alimentando o painel. Webhook que ainda pede ação (amarelo ou vermelho) guarda o corpo por 90 dias, não 30 — é dele que sai a venda reprocessada.'; revoke all on function private.aplicar_retencao(integer) from public, anon, authenticated;
